/* Generated by the build from scripts/service-worker.js. Do not edit dist/sw.js. */
const VERSION = "0.1.0";
const CACHE_NAME = "tsc-gm-0.1.0-441fffa3";
const BASE = "/TSC_GM_COMPANION_TEST/";
const PRECACHE = [
  "/TSC_GM_COMPANION_TEST/assets/index-48PFaU-O.js",
  "/TSC_GM_COMPANION_TEST/assets/index-BX80PwVI.css",
  "/TSC_GM_COMPANION_TEST/icons/icon-192.png",
  "/TSC_GM_COMPANION_TEST/icons/icon-512.png",
  "/TSC_GM_COMPANION_TEST/index.html",
  "/TSC_GM_COMPANION_TEST/manifest.webmanifest",
  "/TSC_GM_COMPANION_TEST/precache-manifest.json"
];

/*
 * Service worker body.
 *
 * The build prepends VERSION, CACHE_NAME and PRECACHE to this file. The whole
 * app is cached on install; every same-origin GET is served from a cache first,
 * so a relaunch works with no network at all.
 *
 * A new version installs and waits. It activates only when the GM applies it
 * (SKIP_WAITING) or on the next launch after every client is gone. The page that
 * applies it reloads itself. Other open tabs keep their session: their own cache
 * is kept, and their requests are served from that cache, including fixed-name
 * files such as index.html and the manifest.
 */

const OFFLINE_FALLBACK = BASE + 'index.html'
const APP_CACHE_PREFIX = 'tsc-gm-'
// Not part of the app caches: it holds only the client-to-build map.
const CLIENTS_CACHE = 'tsc-clients'
const CLIENTS_KEY = '/clients.json'

// Which cache each connected page said it is running, from the files it loaded.
const clientCaches = new Map()
let cleaning = false

self.addEventListener('install', (event) => {
  // No skipWaiting here: a new version must wait for a deliberate action.
  event.waitUntil(precacheAll())
})

async function precacheAll() {
  const cache = await caches.open(CACHE_NAME)
  // If any file fails, this rejects and the install fails. No partial cache is
  // ever presented as ready by the app.
  await cache.addAll(PRECACHE)
}

async function repairCache() {
  const cache = await caches.open(CACHE_NAME)

  for (const url of PRECACHE) {
    const existing = await cache.match(url)
    if (existing) {
      continue
    }

    const response = await fetch(url, { cache: 'reload' })
    if (!response || !response.ok) {
      const status = response ? response.status : 'no response'
      throw new Error(`Could not download ${url} (${status}).`)
    }
    await cache.put(url, response)
  }
}

self.addEventListener('activate', (event) => {
  // Claim only pages that no worker controls yet (a first visit). Pages already
  // controlled by the previous worker are switched by the browser itself, which
  // is why old caches are preserved while their tabs remain open.
  event.waitUntil(self.clients.claim())
})

self.addEventListener('message', (event) => {
  const data = event.data || {}

  if (data.type === 'SKIP_WAITING') {
    self.skipWaiting()
    return
  }

  if (data.type === 'STATUS') {
    const port = event.ports && event.ports[0]
    if (port) {
      port.postMessage({ type: 'STATUS', cacheName: CACHE_NAME })
    }
    return
  }

  if (data.type === 'REPAIR') {
    const port = event.ports && event.ports[0]
    event.waitUntil(
      (async () => {
        try {
          await repairCache()
          if (port) {
            port.postMessage({ ok: true })
          }
        } catch (error) {
          if (port) {
            port.postMessage({
              ok: false,
              error: error && error.message ? error.message : String(error),
            })
          }
        }
      })(),
    )
    return
  }

  if (data.type === 'HELLO') {
    if (event.source && event.source.id) {
      clientCaches.set(event.source.id, typeof data.cacheName === 'string' ? data.cacheName : null)
    }
    event.waitUntil(
      (async () => {
        await saveClientCaches()
        await cleanupCaches()
      })(),
    )
  }
})

/** The worker can be restarted, so the client map is also kept in a cache. */
async function loadClientCaches() {
  try {
    const cache = await caches.open(CLIENTS_CACHE)
    const response = await cache.match(CLIENTS_KEY)
    if (!response) {
      return
    }
    const stored = await response.json()
    for (const [clientId, cacheName] of Object.entries(stored)) {
      if (!clientCaches.has(clientId)) {
        clientCaches.set(clientId, typeof cacheName === 'string' ? cacheName : null)
      }
    }
  } catch {
    // A missing or corrupt map only means requests fall back to the newest cache.
  }
}

async function saveClientCaches() {
  try {
    const cache = await caches.open(CLIENTS_CACHE)
    const stored = Object.fromEntries(clientCaches)
    await cache.put(
      CLIENTS_KEY,
      new Response(JSON.stringify(stored), { headers: { 'content-type': 'application/json' } }),
    )
  } catch {
    // Saving the map is an optimisation for worker restarts, never a requirement.
  }
}

async function clientCacheFor(clientId) {
  if (!clientId) {
    return null
  }
  if (!clientCaches.has(clientId)) {
    await loadClientCaches()
  }
  return clientCaches.get(clientId) ?? null
}

/** Forget pages that have closed, so their caches are not kept forever. */
function pruneClosedClients(windows) {
  const live = new Set(windows.map((client) => client.id))
  for (const id of [...clientCaches.keys()]) {
    if (!live.has(id)) {
      clientCaches.delete(id)
    }
  }
}

/**
 * Deletes app-owned caches that no connected page is using.
 *
 * It waits until every window the worker can see has reported its cache, so a
 * page that is still loading, frozen, or running an older build keeps its files.
 * Caches this app did not create are never touched.
 */
async function cleanupCaches() {
  if (cleaning) {
    return
  }
  cleaning = true

  try {
    let windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
    if (windows.length === 0) {
      return
    }
    pruneClosedClients(windows)

    // The worker may have been restarted since a page said hello, so ask every
    // open page which cache it uses before deleting anything. A page that does
    // not answer (for example a frozen tab) blocks cleanup rather than losing
    // its files.
    if (windows.some((client) => !clientCaches.has(client.id))) {
      for (const client of windows) {
        client.postMessage({ type: 'WHO' })
      }
      await new Promise((resolve) => setTimeout(resolve, 400))
      windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true })
      pruneClosedClients(windows)
    }

    if (windows.length === 0 || windows.some((client) => !clientCaches.has(client.id))) {
      return
    }

    const keep = new Set([CACHE_NAME])
    for (const cacheName of clientCaches.values()) {
      if (cacheName) {
        keep.add(cacheName)
      }
    }

    const names = await caches.keys()
    await Promise.all(
      names
        .filter((name) => name.startsWith(APP_CACHE_PREFIX) && !keep.has(name))
        .map((name) => caches.delete(name)),
    )
    await saveClientCaches()
  } finally {
    cleaning = false
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') {
    return
  }

  const url = new URL(request.url)
  if (url.origin !== self.location.origin) {
    return
  }

  event.respondWith(serve(request, event.clientId))
})

async function serve(request, clientId) {
  // A page that identified its build gets that build's files, fixed names
  // included, for as long as it stays open.
  const clientCacheName = await clientCacheFor(clientId)
  if (clientCacheName) {
    const clientCache = await caches.open(clientCacheName)
    const hit = await clientCache.match(request)
    if (hit) {
      return hit
    }
  }

  const cache = await caches.open(CACHE_NAME)
  const cached = await cache.match(request)
  if (cached) {
    return cached
  }

  // A page that has not identified itself yet, or asks for an older asset, may
  // still be served from another cache this app owns.
  const older = await matchAppCache(request)
  if (older) {
    return older
  }

  if (request.mode === 'navigate') {
    const index = (await cache.match(OFFLINE_FALLBACK)) || (await matchAppCache(OFFLINE_FALLBACK))
    if (index) {
      return index
    }
  }

  try {
    return await fetch(request)
  } catch (error) {
    if (request.mode === 'navigate') {
      const index = (await cache.match(OFFLINE_FALLBACK)) || (await matchAppCache(OFFLINE_FALLBACK))
      if (index) {
        return index
      }
    }
    throw error
  }
}

async function matchAppCache(request) {
  for (const name of await caches.keys()) {
    if (name === CACHE_NAME || !name.startsWith(APP_CACHE_PREFIX)) {
      continue
    }
    const cache = await caches.open(name)
    const hit = await cache.match(request)
    if (hit) {
      return hit
    }
  }
  return undefined
}
